query1:
query  {
  users(id: 1) {
    id
    username
    email
    posts {
      title
      content
    }
  }
}

query2:
fragment PostData on Posts {
  title
  content
}

fragment UserData on Users {
  id
  username
  email
  posts {
    ...PostData
  }
}

query  {
  users(id: 1) {
    ...UserData
  }
}
